BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TYPE risk_class AS ENUM ('read', 'write_soft', 'write_hard', 'dangerous');
CREATE TYPE job_status AS ENUM ('queued', 'running', 'waiting', 'needs_human', 'succeeded', 'failed', 'cancelled');
CREATE TABLE households (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (length(name) BETWEEN 1 AND 200), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL CHECK (length(display_name) BETWEEN 1 AND 200), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (household_id uuid NOT NULL REFERENCES households(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK (role IN ('owner', 'member', 'guest')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (household_id, user_id));
CREATE TABLE threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households(id), created_by uuid NOT NULL REFERENCES users(id), title text, summary text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES threads(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('user', 'assistant', 'system', 'developer', 'tool')), content jsonb NOT NULL, channel text NOT NULL CHECK (channel IN ('api', 'chat', 'voice', 'scheduler', 'worker')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_thread_time_idx ON messages (thread_id, created_at, id);
CREATE TABLE runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES threads(id), actor_id uuid NOT NULL REFERENCES users(id), correlation_id uuid NOT NULL UNIQUE, model_provider text NOT NULL, model_name text NOT NULL, prompt_release text NOT NULL, capability_manifest jsonb NOT NULL, status text NOT NULL CHECK (status IN ('queued', 'running', 'waiting', 'succeeded', 'failed', 'cancelled')), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE memories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households(id), subject text NOT NULL, scope text NOT NULL, kind text NOT NULL, content text NOT NULL, source jsonb NOT NULL, confidence numeric(4,3) NOT NULL CHECK (confidence BETWEEN 0 AND 1), sensitivity text NOT NULL CHECK (sensitivity IN ('public', 'personal', 'sensitive', 'restricted')), valid_from timestamptz NOT NULL DEFAULT now(), valid_until timestamptz, embedding vector, review_status text NOT NULL DEFAULT 'pending' CHECK (review_status IN ('pending', 'accepted', 'rejected')), created_at timestamptz NOT NULL DEFAULT now(), CHECK (valid_until IS NULL OR valid_until > valid_from));
CREATE INDEX memories_scope_idx ON memories (household_id, scope, kind);
CREATE TABLE capabilities (name text NOT NULL, version integer NOT NULL CHECK (version > 0), description text NOT NULL, risk risk_class NOT NULL, required_scopes text[] NOT NULL DEFAULT '{}', input_schema jsonb NOT NULL, output_schema jsonb NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (name, version));
CREATE TABLE idempotency_records (namespace text NOT NULL, idempotency_key text NOT NULL, request_digest char(64) NOT NULL, status text NOT NULL CHECK (status IN ('executing', 'completed', 'failed')), response jsonb, lease_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (namespace, idempotency_key));
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households(id), created_by uuid NOT NULL REFERENCES users(id), kind text NOT NULL, schema_version integer NOT NULL DEFAULT 1 CHECK (schema_version > 0), idempotency_key text NOT NULL, input jsonb NOT NULL, input_digest char(64) NOT NULL, status job_status NOT NULL DEFAULT 'queued', version integer NOT NULL DEFAULT 1 CHECK (version > 0), result jsonb, error_code text, lease_owner text, lease_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (household_id, kind, idempotency_key));
CREATE INDEX jobs_claim_idx ON jobs (status, created_at) WHERE status IN ('queued', 'running', 'waiting');
CREATE TABLE job_events (job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, sequence integer NOT NULL CHECK (sequence > 0), event_type text NOT NULL, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (job_id, sequence));
CREATE TABLE confirmations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES households(id), actor_id uuid NOT NULL REFERENCES users(id), action_digest char(64) NOT NULL, risk risk_class NOT NULL CHECK (risk IN ('write_hard', 'dangerous')), nonce text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK (expires_at > created_at));
CREATE TABLE audit_events (household_id uuid NOT NULL REFERENCES households(id), sequence bigint NOT NULL CHECK (sequence > 0), id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), occurred_at timestamptz NOT NULL DEFAULT now(), event_type text NOT NULL, actor_id uuid NOT NULL, correlation_id uuid NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, payload jsonb NOT NULL, previous_hash char(64) NOT NULL, event_hash char(64) NOT NULL, PRIMARY KEY (household_id, sequence), UNIQUE (household_id, event_hash));
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_type text NOT NULL, aggregate_id text NOT NULL, event_type text NOT NULL, schema_version integer NOT NULL DEFAULT 1 CHECK (schema_version > 0), payload jsonb NOT NULL, correlation_id uuid NOT NULL, causation_id uuid, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0));
CREATE INDEX outbox_unpublished_idx ON outbox_events (created_at) WHERE published_at IS NULL;
COMMIT;
